import { MakeLogicType, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'

import { metricsAttributeValuesRetrieve } from '../../generated/api'
import { canViewMetrics } from '../../metricsAccess'
import { metricsViewerLogic, resolveDate } from '../metricsViewerLogic'
import { DROPPED_LABELS_ATTRIBUTE, droppedLabelKeys } from './droppedLabels'

const MARKER_VALUES_LIMIT = 100

export interface DroppedLabelsResult {
    scope: string
    keys: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsDroppedLabelsLogicValues {
    currentTeamId: number | null // metricsViewerLogic
    dateFrom: string | null // metricsViewerLogic
    dateTo: string | null // metricsViewerLogic
    metricName: string // metricsViewerLogic
    timezone: string // metricsViewerLogic
    droppedLabels: string[]
    droppedLabelsResult: DroppedLabelsResult | null
    droppedLabelsResultLoading: boolean
    scope: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsDroppedLabelsLogicActions {
    loadDroppedLabels: (scope: string) => string
    loadDroppedLabelsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadDroppedLabelsSuccess: (
        droppedLabelsResult: {
            keys: string[]
            scope: string
        },
        payload?: string
    ) => {
        droppedLabelsResult: {
            keys: string[]
            scope: string
        }
        payload?: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface metricsDroppedLabelsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        scope: (
            metricName: string,
            dateFrom: string | null,
            dateTo: string | null,
            currentTeamId: number | null
        ) => string
        droppedLabels: (droppedLabelsResult: DroppedLabelsResult | null, scope: string) => string[]
    }
}

export type metricsDroppedLabelsLogicType = MakeLogicType<
    metricsDroppedLabelsLogicValues,
    metricsDroppedLabelsLogicActions,
    Record<string, any>,
    metricsDroppedLabelsLogicMeta
>

export const metricsDroppedLabelsLogic = kea<metricsDroppedLabelsLogicType>([
    path(['products', 'metrics', 'frontend', 'components', 'DroppedLabels', 'metricsDroppedLabelsLogic']),
    connect(() => ({
        values: [metricsViewerLogic, ['metricName', 'dateFrom', 'dateTo', 'timezone', 'currentTeamId']],
    })),
    loaders(({ values }) => ({
        droppedLabelsResult: [
            null as DroppedLabelsResult | null,
            {
                loadDroppedLabels: async (scope: string, breakpoint) => {
                    const metricName = values.metricName.trim()
                    if (!canViewMetrics() || !values.currentTeamId || !metricName) {
                        return { scope, keys: [] }
                    }
                    await breakpoint(300)
                    const dateFrom = resolveDate(values.dateFrom, values.timezone)
                    const dateTo = resolveDate(values.dateTo, values.timezone)
                    const response = await metricsAttributeValuesRetrieve(String(values.currentTeamId), {
                        key: DROPPED_LABELS_ATTRIBUTE,
                        metricName,
                        ...(dateFrom ? { dateFrom } : {}),
                        ...(dateTo ? { dateTo } : {}),
                        limit: MARKER_VALUES_LIMIT,
                    })
                    breakpoint()
                    return { scope, keys: droppedLabelKeys(response.results.map((row) => row.name)) }
                },
            },
        ],
    })),
    selectors({
        scope: [
            (s) => [s.metricName, s.dateFrom, s.dateTo, s.currentTeamId],
            (metricName: string, dateFrom: string | null, dateTo: string | null, teamId: number | null): string =>
                JSON.stringify([metricName.trim(), dateFrom, dateTo, teamId]),
        ],
        // Empty until the result for the current metric and range arrives, so the banner never shows
        // the keys of the metric the user just left.
        droppedLabels: [
            (s) => [s.droppedLabelsResult, s.scope],
            (result: DroppedLabelsResult | null, scope: string): string[] =>
                result && result.scope === scope ? result.keys : [],
        ],
    }),
    subscriptions(({ actions }) => ({
        scope: (scope: string) => actions.loadDroppedLabels(scope),
    })),
])
